'use strict';

const assert = require('assert');
const nconf = require('nconf');

const db = require('./mocks/databasemock');
const topics = require('../src/topics');
const posts = require('../src/posts');
const categories = require('../src/categories');
const user = require('../src/user');
const meta = require('../src/meta');

describe('Topic Backlinks', () => {
	let uid;
	let cid;
	let target;
	let source;
	let previousSetting;

	before(async () => {
		previousSetting = meta.config.topicBacklinks;
		meta.config.topicBacklinks = 1;
		uid = await user.create({ username: 'backlink-author', password: '123456' });
		cid = (await categories.create({ name: 'Backlink Category' })).cid;
		target = await topics.post({ title: 'Backlink target', content: 'A target topic post', uid, cid });
	});

	after(() => {
		meta.config.topicBacklinks = previousSetting;
	});

	it('rejects invalid post data', async () => {
		await assert.rejects(topics.syncBacklinks(), { message: '[[error:invalid-data]]' });
	});

	it('adds a backlink for a new topic and keeps one association per post', async () => {
		const { tid } = target.topicData;
		source = await topics.post({
			title: 'Backlink source',
			content: `See ${nconf.get('url')}/topic/${tid}/backlink-target and /topic/${tid}`,
			uid,
			cid,
		});
		const { pid } = source.postData;
		assert.deepStrictEqual(await db.getSortedSetRange(`pid:${pid}:backlinks`, 0, -1), [String(tid)]);
		const events = (await topics.events.get(tid, uid)).filter(event => event.type === 'backlink');
		assert.strictEqual(events.length, 1);
		assert.strictEqual(events[0].href, `/post/${pid}`);
		assert.strictEqual(events[0].uid, uid);
		assert.strictEqual(events[0].text, '[[topic:backlink]]');
		assert.strictEqual(await topics.syncBacklinks(source.postData), 0);
	});

	it('hides events when disabled and removes them after an edit', async () => {
		const { tid } = target.topicData;
		meta.config.topicBacklinks = 0;
		assert.strictEqual((await topics.events.get(tid, uid)).filter(event => event.type === 'backlink').length, 0);
		meta.config.topicBacklinks = 1;
		await posts.edit({ pid: source.postData.pid, uid, content: 'This post no longer links to another topic.' });
		assert.deepStrictEqual(await db.getSortedSetRange(`pid:${source.postData.pid}:backlinks`, 0, -1), []);
		assert.strictEqual((await topics.events.get(tid, uid)).filter(event => event.type === 'backlink').length, 0);
	});
});

	},
};

Events.init = async () => {
	// Allow plugins to define additional topic event types
	const { types } = await plugins.hooks.fire('filter:topicEvents.init', { types: Events._types });
	Events._types = types;
};

Events.get = async (tid, uid) => {
	const topics = require('.');

	if (!await topics.exists(tid)) {
		throw new Error('[[error:no-topic]]');
	}

	let eventIds = await db.getSortedSetRangeWithScores(`topic:${tid}:events`, 0, -1);
	const keys = eventIds.map(obj => `topicEvent:${obj.value}`);
	const timestamps = eventIds.map(obj => obj.score);
	eventIds = eventIds.map(obj => obj.value);
	let events = await db.getObjects(keys);
	if (!meta.config.topicBacklinks) {
		events = events.map(event => (event && event.type === 'backlink' ? null : event));
	}
	events = await modifyEvent({ tid, uid, eventIds, timestamps, events });

	return events;
};

async function getUserInfo(uids) {
	uids = uids.filter((uid, idx) => !isNaN(parseInt(uid, 10)) && uids.indexOf(uid) === idx);
	const userData = await user.getUsersFields(uids, ['picture', 'username', 'userslug']);
	const userMap = userData.reduce((memo, cur) => memo.set(cur.uid, cur), new Map());
	userMap.set('system', {
		system: true,
	});

	return userMap;
}

async function getCategoryInfo(cids) {
	const uniqCids = _.uniq(cids);
	const catData = await categories.getCategoriesFields(uniqCids, ['name', 'slug', 'icon', 'color', 'bgColor']);
	return _.zipObject(uniqCids, catData);
}

async function modifyEvent({ tid, uid, eventIds, timestamps, events }) {
	// Add posts from post queue
	const isPrivileged = await user.isPrivileged(uid);
	if (isPrivileged) {
		const queuedPosts = await posts.getQueuedPosts({ tid }, { metadata: false });
		Object.assign(events, queuedPosts.map(item => ({
			type: 'post-queue',
			timestamp: item.data.timestamp || Date.now(),
			uid: item.data.uid,
		})));
		queuedPosts.forEach((item) => {
			timestamps.push(item.data.timestamp || Date.now());
		});
	}

	// Keep ids and timestamps aligned when hidden or missing events are removed.
	const visible = events.map((event, idx) => ({ event, id: eventIds[idx], timestamp: timestamps[idx] }))
		.filter(item => item.event && Events._types.hasOwnProperty(item.event.type));
	events = visible.map(item => item.event);
	eventIds = visible.map(item => item.id);
	timestamps = visible.map(item => item.timestamp);

	const [users, fromCategories] = await Promise.all([
		getUserInfo(events.map(event => event.uid).filter(Boolean)),
		getCategoryInfo(events.map(event => event.fromCid).filter(Boolean)),
	]);

	// Add user & metadata
	events.forEach((event, idx) => {
		event.id = parseInt(eventIds[idx], 10);
		event.timestamp = timestamps[idx];
		event.timestampISO = new Date(timestamps[idx]).toISOString();
		if (event.type === 'backlink') {
			event.uid = parseInt(event.uid, 10);
		}
		if (event.hasOwnProperty('uid')) {
			event.user = users.get(event.uid === 'system' ? 'system' : parseInt(event.uid, 10));
		}
		if (event.hasOwnProperty('fromCid')) {
			event.fromCategory = fromCategories[event.fromCid];
			event.text = `[[topic:moved-from-by, ${event.fromCategory.name}]]`;
		}

		Object.assign(event, Events._types[event.type]);
	});

	// Sort events
	events.sort((a, b) => a.timestamp - b.timestamp);

	return events;
}

